        len = strlen(szWord);
        val = gf_get_bit_size(len);
        gf_bs_write_int(bs, val, 5);
        gf_bs_write_int(bs, len, val);
        for (i=0; i<len; i++) gf_bs_write_int(bs, szWord[i], 8);

        gf_bs_align(bs);
        gf_bs_get_content(bs, &buf, &buf_size);
        gf_bs_del(bs);

        ifce->DispatchFrame(ifce, buf, buf_size);
        gf_free(buf);
}

