#define MAX_JACK_CLIENT_NAME_SZ 128
/*
 * This structure defines the handle to a Jack driver
 */
typedef struct
{
        char jackClientName[MAX_JACK_CLIENT_NAME_SZ];
        jack_client_t *jack;
        jack_port_t **jackPorts;
        jack_nframes_t currentBlockSize;
        u32 numChannels;
