 static Bool latm_dmx_process_event(GF_Filter *filter, const GF_FilterEvent *evt)
 {
        u32 i;
        GF_FilterEvent fevt;
        GF_LATMDmxCtx *ctx = gf_filter_get_udta(filter);

        switch (evt->base.type) {
        case GF_FEVT_PLAY:
                if (!ctx->is_playing) {
                        ctx->is_playing = GF_TRUE;
                        ctx->cts = 0;
                }
                if (! ctx->is_file) {
                        if (evt->play.start_range || ctx->initial_play_done) {
                                ctx->latm_buffer_size = 0;
                                ctx->resume_from = 0;
                        }

                        ctx->initial_play_done = GF_TRUE;
                        return GF_FALSE;
                }
                ctx->start_range = evt->play.start_range;
                ctx->in_seek = GF_TRUE;
                ctx->file_pos = 0;
                if (ctx->start_range) {
                        for (i=1; i<ctx->index_size; i++) {
                                if (ctx->indexes[i].duration>ctx->start_range) {
                                        ctx->cts = (u64) (ctx->indexes[i-1].duration * GF_M4ASampleRates[ctx->sr_idx]);
                                        ctx->file_pos = ctx->indexes[i-1].pos;
                                        break;
                                }
                        }
                }
                if (!ctx->initial_play_done) {
                        ctx->initial_play_done = GF_TRUE;
                        //seek will not change the current source state, don't send a seek
                        if (!ctx->file_pos)
                                return GF_TRUE;
                }
                ctx->latm_buffer_size = 0;
                ctx->resume_from = 0;
                //post a seek
                GF_FEVT_INIT(fevt, GF_FEVT_SOURCE_SEEK, ctx->ipid);
                fevt.seek.start_offset = ctx->file_pos;
                gf_filter_pid_send_event(ctx->ipid, &fevt);

                //cancel event
                return GF_TRUE;

        case GF_FEVT_STOP:
                //don't cancel event
                ctx->is_playing = GF_FALSE;
                return GF_FALSE;

        case GF_FEVT_SET_SPEED:
                //cancel event
                return GF_TRUE;
        default:
                break;
        }
        //by default don't cancel event - to rework once we have downloading in place
        return GF_FALSE;
 }

 static GFINLINE void latm_dmx_update_cts(GF_LATMDmxCtx *ctx)
 {
        assert(ctx->dts_inc);

        if (ctx->timescale) {
                u64 inc = ctx->dts_inc;
                inc *= ctx->timescale;
                inc /= GF_M4ASampleRates[ctx->sr_idx];
                ctx->cts += inc;
        } else {
                ctx->cts += ctx->dts_inc;
        }
 }

