  1217                  }
  1218                  else {
  1219                          cfg->sbr_sr = GF_M4ASampleRates[cfg->sbr_sr_index];
  1220                  }
  1221                  cfg->sbr_object_type = gf_bs_read_int_log(bs, 5, "sbr_object_type");
  1222                  if (cfg->sbr_object_type==31)
  1223                          cfg->sbr_object_type = 32 + gf_bs_read_int_log(bs, 6, "audioObjectTypeExt");
  1224                  audio_obj_type = cfg->sbr_object_type;
